CREATE OR REPLACE FUNCTION public.calculate_aa_es_amounts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    item JSONB;
    total_est DECIMAL(15, 2) := 0;
    total_justified DECIMAL(15, 2) := 0;
    total_aa_es DECIMAL(15, 2) := 0;
    period INT;
    qty DECIMAL;
    effective_qty DECIMAL;
    rate DECIMAL;
    esic_total DECIMAL(15, 2) := 0;
    epf_total DECIMAL(15, 2) := 0;
    bonus_total DECIMAL(15, 2) := 0;
    gst_amount DECIMAL(15, 2) := 0;
    is_7_day BOOLEAN := FALSE;
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.status = 'Approved' THEN
        IF current_setting('app.current_user_role', true) <> 'superuser' THEN
             RAISE EXCEPTION 'Cannot edit an Approved AA & ES. Contact Superuser.';
        END IF;
    END IF;

    IF NEW.type = 'Market' THEN
        FOR item IN SELECT * FROM jsonb_array_elements(NEW.boq)
        LOOP
            qty := (item->>'qty')::DECIMAL;
            rate := (item->>'rate')::DECIMAL;
            gst_amount := gst_amount + (qty * rate * (REPLACE(item->>'gst', '%', '')::DECIMAL / 100));
            total_est := total_est + (qty * rate);
        END LOOP;
        NEW.estimated_cost := ROUND(total_est);
        NEW.justified_amount := ROUND(total_est);
        NEW.aa_es_amount := ROUND(total_est + gst_amount);

    ELSIF NEW.type = 'Manpower' THEN
        period := (NEW.boq->>'Period')::INT;
        is_7_day := COALESCE((NEW.boq->>'is_7_day')::BOOLEAN, FALSE);

        FOR item IN SELECT * FROM jsonb_array_elements(NEW.boq->'Items')
        LOOP
            qty := (item->>'qty')::DECIMAL;
            rate := (item->>'rate')::DECIMAL;
            effective_qty := CASE WHEN is_7_day THEN qty * (7.0 / 6.0) ELSE qty END;

            total_est := total_est + (effective_qty * rate * period);

            IF (NEW.boq->>'ESIC')::BOOLEAN THEN esic_total := esic_total + (effective_qty * period * 0.0325 * LEAST(rate, 21000)); END IF;
            IF (NEW.boq->>'EPF')::BOOLEAN THEN epf_total := epf_total + (effective_qty * period * 0.13 * LEAST(rate, 15000)); END IF;
            IF (NEW.boq->>'Bonus')::BOOLEAN THEN bonus_total := bonus_total + (effective_qty * period * 0.0833 * LEAST(rate, 21000)); END IF;
        END LOOP;

        -- 1. ROUND Estimated Cost
        NEW.estimated_cost := ROUND(total_est);

        -- 2. ROUND Justified Amount (EC + 15% CPOH)
        NEW.justified_amount := ROUND(NEW.estimated_cost * 1.15);

        -- 3. GST (18% of Justified) - NO ROUNDING
        gst_amount := NEW.justified_amount * 0.18;

        -- 4. ROUND Grand Total
        NEW.aa_es_amount := ROUND(NEW.justified_amount + gst_amount + esic_total + epf_total + bonus_total);
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_gross_wage(p_employee_id integer, p_from_date date, p_to_date date)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_agreement_id INT; v_wage_unit wage_unit; v_wage_rate DECIMAL;
    p_days INT; a_days INT; l_days INT; gross_wage DECIMAL := 0;
    designation_count INT; is_complete_month BOOLEAN;
BEGIN
    SELECT e.agreement_id, wi.unit, get_effective_rate(p_from_date, wi.id) INTO v_agreement_id, v_wage_unit, v_wage_rate
    FROM employees e JOIN wage_items wi ON e.designation = wi.item_name WHERE e.id = p_employee_id;
    IF v_wage_rate IS NULL THEN RAISE EXCEPTION 'No valid wage rate found for employee ID % on date %.', p_employee_id, p_from_date; END IF;
    SELECT COUNT(*) FILTER (WHERE status = 'P'), COUNT(*) FILTER (WHERE status = 'A'), COUNT(*) FILTER (WHERE status = 'L') INTO p_days, a_days, l_days
    FROM attendance_records WHERE employee_id = p_employee_id AND attendance_date BETWEEN p_from_date AND p_to_date;
    IF v_wage_unit = 'Per Person Per Day' THEN gross_wage := p_days * v_wage_rate;
    ELSE
        SELECT COUNT(DISTINCT designation) INTO designation_count FROM employees WHERE agreement_id = v_agreement_id;
        is_complete_month := (p_from_date = date_trunc('month', p_from_date) AND p_to_date = (date_trunc('month', p_from_date) + interval '1 month - 1 day')::date);
        IF designation_count = 1 OR NOT is_complete_month THEN gross_wage := p_days * v_wage_rate / 26;
        ELSE
            IF (p_days + l_days + a_days) > 0 THEN gross_wage := p_days * v_wage_rate / (p_days + l_days + a_days);
            ELSE gross_wage := 0; END IF;
        END IF;
    END IF;
    RETURN gross_wage;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_agreement_with_inheritance(p_officeid integer, p_agreement_no character varying, p_agency_id integer, p_aa_es_id integer, p_service_charge numeric, p_tendered_amount numeric, p_period daterange, p_esic boolean, p_epf boolean, p_predecessor_id integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_new_id INT;
    v_next_start_date DATE;
    v_is_bound BOOLEAN;
BEGIN
    -- 1. Check if AA_ES is already bound across ALL entity types
    SELECT EXISTS (
        SELECT 1 FROM agreements WHERE aa_es_id = p_aa_es_id
        UNION ALL
        SELECT 1 FROM work_orders WHERE aa_es_id = p_aa_es_id
        UNION ALL
        SELECT 1 FROM supply_orders WHERE aa_es_id = p_aa_es_id
    ) INTO v_is_bound;

    IF v_is_bound THEN
        RAISE EXCEPTION 'AA_ES ID % is already bound to another Agreement, Work Order, or Supply Order.', p_aa_es_id;
    END IF;

    -- 2. Validate Continuity if predecessor exists
    IF p_predecessor_id IS NOT NULL THEN
        SELECT upper(period) INTO v_next_start_date FROM agreements WHERE id = p_predecessor_id;

        IF v_next_start_date IS NULL THEN
             RAISE EXCEPTION 'Predecessor Agreement ID % not found or has invalid period.', p_predecessor_id;
        END IF;

        IF lower(p_period) != v_next_start_date THEN
            RAISE EXCEPTION 'Continuity Error: New agreement must start on %.', v_next_start_date;
        END IF;
    END IF;

    -- 3. Create the New Agreement
    INSERT INTO agreements (
        officeid, agreement_no, agency_id, aa_es_id, 
        service_charge_percent, tendered_amount, period, 
        bill_type_esic, bill_type_epf, predecessor_id, status
    ) VALUES (
        p_officeid, p_agreement_no, p_agency_id, p_aa_es_id,
        p_service_charge, p_tendered_amount, p_period,
        p_esic, p_epf, p_predecessor_id, 'Active'
    ) RETURNING id INTO v_new_id;

    -- 4. Inherit Employees
    IF p_predecessor_id IS NOT NULL THEN
        -- Copy Bio-data to new records
        -- Note: Removed 'status' as it is handled by the presence of leaving_date
        INSERT INTO employees (
            officeid, agreement_id, full_name, designation, 
            account_no, ifsc, bank_name, uan_no, esic_no,
            joining_date, default_rest_day, is_reliever
        )
        SELECT 
            p_officeid, v_new_id, full_name, designation,
            account_no, ifsc, bank_name, uan_no, esic_no,
            lower(p_period), default_rest_day, is_reliever
        FROM employees
        WHERE agreement_id = p_predecessor_id AND (leaving_date IS NULL OR leaving_date >= v_next_start_date);

        -- Mark old employees as left on the day the old agreement ended
        UPDATE employees 
        SET leaving_date = v_next_start_date - 1
        WHERE agreement_id = p_predecessor_id AND (leaving_date IS NULL OR leaving_date >= v_next_start_date);
    END IF;

    RETURN v_new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_crud(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_action TEXT := upper(p_input->>'Action');
    v_table_name TEXT := p_input->>'Table';
    v_payload jsonb := p_input->'Payload';
    v_real_table_name TEXT;
    v_pk_column TEXT;
    v_pk_type TEXT;
    v_pk_value TEXT;
    v_sql TEXT;
    v_result jsonb;
    v_col_list TEXT;
    v_key TEXT;
    v_val TEXT;
BEGIN
    -- 1. Validate Table existence via registry and get the correct case-sensitive name
    SELECT table_name INTO v_real_table_name 
    FROM public.registry_tables 
    WHERE lower(table_name) = lower(v_table_name);

    IF v_real_table_name IS NULL THEN
        RAISE EXCEPTION 'Table % is not registered or does not exist in the schema.', v_table_name;
    END IF;

    -- 2. Identify Primary Key column and its data type for exact filtering/joining
    SELECT a.attname, format_type(a.atttypid, a.atttypmod)
    INTO v_pk_column, v_pk_type
    FROM pg_index i
    JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey)
    WHERE i.indrelid = format('public.%I', v_real_table_name)::regclass 
    AND i.indisprimary;

    -- 3. Execute Action logic
    CASE v_action
        WHEN 'INSERT' THEN
            -- Inserts a new record using jsonb_populate_record to map keys to columns and handle types
            v_sql := format('INSERT INTO public.%I SELECT * FROM jsonb_populate_record(NULL::public.%I, %L) RETURNING to_jsonb(public.%I.*)', 
                            v_real_table_name, v_real_table_name, v_payload, v_real_table_name);
            EXECUTE v_sql INTO v_result;

        WHEN 'UPDATE' THEN
            -- Updates an existing record. Requires the primary key in the payload.
            v_pk_value := v_payload->>v_pk_column;
            IF v_pk_value IS NULL THEN
                RAISE EXCEPTION 'Primary key % must be provided in the Payload for UPDATE operations.', v_pk_column;
            END IF;

            -- Retrieve all columns to perform a row-level update
            SELECT string_agg(quote_ident(attname), ', ') INTO v_col_list
            FROM pg_attribute 
            WHERE attrelid = format('public.%I', v_real_table_name)::regclass 
            AND attnum > 0 AND NOT attisdropped;

            -- Uses jsonb_populate_record(t, payload) to merge JSON updates into the existing row t
            v_sql := format('UPDATE public.%I t SET (%s) = (SELECT %s FROM jsonb_populate_record(t, %L)) WHERE %I = %L::%s RETURNING to_jsonb(t.*)',
                            v_real_table_name, v_col_list, v_col_list, v_payload, v_pk_column, v_pk_value, v_pk_type);
            EXECUTE v_sql INTO v_result;

        WHEN 'DELETE' THEN
            -- Deletes a record identified by the primary key in the payload.
            v_pk_value := v_payload->>v_pk_column;
            IF v_pk_value IS NULL THEN
                RAISE EXCEPTION 'Primary key % must be provided in the Payload for DELETE operations.', v_pk_column;
            END IF;

            v_sql := format('DELETE FROM public.%I t WHERE %I = %L::%s RETURNING to_jsonb(t.*)',
                            v_real_table_name, v_pk_column, v_pk_value, v_pk_type);
            EXECUTE v_sql INTO v_result;

        WHEN 'SELECT', 'READ' THEN
            -- Performs a filtered selection. All keys in the payload are treated as equality filters (AND).
            v_sql := format('SELECT jsonb_agg(to_jsonb(t.*)) FROM public.%I t WHERE TRUE', v_real_table_name);
            IF v_payload IS NOT NULL AND v_payload != '{}'::jsonb THEN
                FOR v_key, v_val IN SELECT * FROM jsonb_each_text(v_payload) LOOP
                    v_sql := v_sql || format(' AND %I::text = %L', v_key, v_val);
                END LOOP;
            END IF;
            EXECUTE v_sql INTO v_result;

        ELSE
            RAISE EXCEPTION 'Unsupported Action: %. Supported actions are INSERT, UPDATE, DELETE, SELECT/READ.', v_action;
    END CASE;

    RETURN v_result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('error', SQLERRM, 'detail', SQLSTATE);
END;
$function$

CREATE OR REPLACE FUNCTION public.fill_employee_attendance(p_employee_id integer, p_office_id integer, p_start_date date, p_end_date date, p_present_days integer[], p_absent_days integer[], p_leave_days integer[], p_rest_days integer[])
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_is_reliever BOOLEAN;
    v_joining DATE;
    v_leaving DATE;
    current_day DATE;
    day_of_month INT;
    status_to_insert attendance_status;
BEGIN
    SELECT is_reliever, joining_date, leaving_date 
    INTO v_is_reliever, v_joining, v_leaving 
    FROM employees WHERE id = p_employee_id;

    FOR current_day IN SELECT generate_series(p_start_date, p_end_date, '1 day'::interval)
    LOOP
        -- Skip if before joining or after leaving
        IF current_day < v_joining OR (v_leaving IS NOT NULL AND current_day > v_leaving) THEN
            CONTINUE;
        END IF;

        day_of_month := EXTRACT(DAY FROM current_day);
        status_to_insert := NULL;

        IF v_is_reliever THEN
            IF day_of_month = ANY(p_present_days) THEN status_to_insert := 'P';
            ELSE status_to_insert := 'L'; END IF;
        ELSE
            IF day_of_month = ANY(p_absent_days) THEN status_to_insert := 'A';
            ELSIF day_of_month = ANY(p_leave_days) THEN status_to_insert := 'L';
            ELSIF day_of_month = ANY(p_rest_days) THEN status_to_insert := 'R';
            ELSE status_to_insert := 'P'; END IF;
        END IF;

        INSERT INTO attendance_records (officeid, employee_id, attendance_date, status)
        VALUES (p_office_id, p_employee_id, current_day, status_to_insert)
        ON CONFLICT (employee_id, attendance_date)
        DO UPDATE SET status = EXCLUDED.status, updated_at = NOW();
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_employee_wages(p_employee_id integer, p_office_id integer, p_month_str text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    start_date DATE := (p_month_str || '-01')::date;
    end_date DATE := (start_date + interval '1 month - 1 day')::date;
    gross_wage DECIMAL;
    epf_deduction DECIMAL := 0;
    esic_deduction DECIMAL := 0;
    is_epf_applicable BOOLEAN;
    is_esic_applicable BOOLEAN;
BEGIN
    DELETE FROM wages_ledger
    WHERE employee_id = p_employee_id
      AND transaction_date BETWEEN start_date AND end_date;

    SELECT ag.bill_type_epf, ag.bill_type_esic
    INTO is_epf_applicable, is_esic_applicable
    FROM employees e JOIN agreements ag ON e.agreement_id = ag.id
    WHERE e.id = p_employee_id;

    gross_wage := calculate_gross_wage(p_employee_id, start_date, end_date);

    IF is_epf_applicable THEN
        epf_deduction := 0.12 * LEAST(gross_wage, 15000);
    END IF;

    IF is_esic_applicable THEN
        esic_deduction := 0.0075 * gross_wage;
    END IF;

    INSERT INTO wages_ledger (officeid, employee_id, transaction_date, remark, cr_amount)
    VALUES (p_office_id, p_employee_id, end_date, 'Gross Wage for ' || p_month_str, gross_wage);

    IF epf_deduction > 0 THEN
        INSERT INTO wages_ledger (officeid, employee_id, transaction_date, remark, dr_amount)
        VALUES (p_office_id, p_employee_id, end_date, 'EPF Deduction', epf_deduction);
    END IF;

    IF esic_deduction > 0 THEN
        INSERT INTO wages_ledger (officeid, employee_id, transaction_date, remark, dr_amount)
        VALUES (p_office_id, p_employee_id, end_date, 'ESIC Deduction', esic_deduction);
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_epf_contribution(p_employee_id integer, p_office_id integer, p_month_str text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_agreement_id INT;
    is_epf_applicable BOOLEAN;
    gross_wage DECIMAL;
    epf_contribution DECIMAL := 0;
    month_start DATE := (p_month_str || '-01')::date;
    month_end DATE := (month_start + interval '1 month - 1 day')::date;
BEGIN
    -- 1. Check if EPF is applicable for the employee's agreement
    SELECT e.agreement_id, ag.bill_type_epf
    INTO v_agreement_id, is_epf_applicable
    FROM employees e
    JOIN agreements ag ON e.agreement_id = ag.id
    WHERE e.id = p_employee_id;

    -- If not applicable, do nothing and exit
    IF NOT is_epf_applicable THEN
        RETURN;
    END IF;

    -- 2. Get the gross wage for the month from the wages_ledger
    SELECT COALESCE(SUM(cr_amount), 0)
    INTO gross_wage
    FROM wages_ledger
    WHERE employee_id = p_employee_id
      AND transaction_date BETWEEN month_start AND month_end;

    -- If no wage was generated, do nothing
    IF gross_wage <= 0 THEN
        RETURN;
    END IF;

    -- 3. Delete any existing EPF record for this period to ensure idempotency
    DELETE FROM epf_ledger
    WHERE employee_id = p_employee_id
      AND transaction_date = month_end;

    -- 4. Calculate EPF contribution
    -- EPF @ 13% of min(15000, Gross Wage)
    epf_contribution := 0.13 * LEAST(gross_wage, 15000);

    -- 5. Insert the new record if contribution is greater than zero
    IF epf_contribution > 0 THEN
        INSERT INTO epf_ledger (officeid, employee_id, transaction_date, remark, cr_amount)
        VALUES (p_office_id, p_employee_id, month_end, 'Employer EPF Contribution for ' || p_month_str, epf_contribution);
    END IF;
END;
$function$

