CREATE OR REPLACE FUNCTION public.generate_membership_no()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_prefix VARCHAR(10);
    v_type_code VARCHAR(5);
    v_name_initial CHAR(1);
    v_seq_init INT;
    v_seq_db INT;
    v_final_seq INT;
BEGIN
    -- 1. Determine Type Code
    CASE NEW.membership_type
        WHEN 'General' THEN v_type_code := 'GEN';
        WHEN 'Associate' THEN v_type_code := 'AM';
        WHEN 'Govt Servant' THEN v_type_code := 'GS';
        WHEN 'Senior Citizen' THEN v_type_code := 'SC';
        ELSE v_type_code := 'OTH';
    END CASE;

    -- 2. Get Name Initial
    v_name_initial := UPPER(SUBSTRING(NEW.full_name FROM 1 FOR 1));

    -- 3. Construct Prefix
    v_prefix := v_type_code || v_name_initial;

    -- 4. Get Sequence from Initializer
    SELECT last_sequence INTO v_seq_init FROM membership_sequences WHERE prefix = v_prefix;
    IF v_seq_init IS NULL THEN v_seq_init := 0; END IF;

    -- 5. Get Max Sequence from DB
    SELECT COALESCE(MAX(NULLIF(regexp_replace(membership_no, '\D', '', 'g'), '')::INT), 0)
    INTO v_seq_db
    FROM members
    WHERE membership_no LIKE v_prefix || '%';

    -- 6. Determine Next Sequence
    v_final_seq := GREATEST(v_seq_init, v_seq_db) + 1;

    -- 7. Assign Number
    NEW.membership_no := v_prefix || v_final_seq;

    -- 8. Set Username and Default Password
    NEW.username := NEW.membership_no;
    -- Default password 'admin123' hashed (bcrypt)
    NEW.password := '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi';

    return NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_wages_for_period(p_employee_id integer, p_office_id integer, p_from date, p_to date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_designation VARCHAR;
    v_unit wage_unit;
    v_item_id INT;
    v_current_date DATE;
    v_status VARCHAR;
    v_rate DECIMAL;
    v_daily_wage DECIMAL;
    v_monthly_total DECIMAL := 0;
    v_last_day_of_month DATE;
    v_days_in_month INT;
BEGIN
    -- Get Employee Designation and Unit
    SELECT e.designation, wi.unit, wi.id 
    INTO v_designation, v_unit, v_item_id
    FROM employees e
    JOIN wage_items wi ON e.designation = wi.item_name
    WHERE e.id = p_employee_id;

    -- Loop through each day in the period
    v_current_date := p_from;
    WHILE v_current_date <= p_to LOOP
        -- 1. Get Attendance Status
        SELECT status INTO v_status FROM attendance_records
        WHERE employee_id = p_employee_id AND attendance_date = v_current_date;

        -- 2. If Present (P) or Rest Day (R), calculate daily wage
        IF v_status IN ('P', 'R') THEN
            v_rate := get_effective_rate(v_current_date, v_item_id);

            IF v_unit = 'Per Person Per Month' THEN
                -- Calculate actual days in the current month
                v_days_in_month := EXTRACT(DAY FROM (DATE_TRUNC('month', v_current_date) + INTERVAL '1 month - 1 day'))::INT;
                v_daily_wage := v_rate / v_days_in_month::DECIMAL;
            ELSE
                -- Per Day rate
                v_daily_wage := v_rate;
            END IF;

            v_monthly_total := v_monthly_total + v_daily_wage;
        END IF;

        -- 3. If it's the last day of the month, post the total and reset
        v_last_day_of_month := (DATE_TRUNC('month', v_current_date) + INTERVAL '1 month - 1 day')::DATE;

        IF v_current_date = v_last_day_of_month OR v_current_date = p_to THEN
            IF v_monthly_total > 0 THEN
                INSERT INTO wages_ledger (officeid, employee_id, transaction_date, cr_amount, remark)
                VALUES (p_office_id, p_employee_id, v_current_date, ROUND(v_monthly_total), 'Monthly Wages Generated (Unit-Aware)');
                v_monthly_total := 0;
            END IF;
        END IF;

        v_current_date := v_current_date + INTERVAL '1 day';
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_effective_rate(p_check_date date, p_item_id integer)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_authority wage_authority;
    v_json_key VARCHAR;
    v_fixed_allowance DECIMAL;
    v_base_rate DECIMAL;
BEGIN
    -- Get item details
    SELECT authority, json_key, fixed_allowance
    INTO v_authority, v_json_key, v_fixed_allowance
    FROM wage_items
    WHERE id = p_item_id;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    -- Get the base rate from the order active on p_check_date
    SELECT (rates ->> v_json_key)::DECIMAL
    INTO v_base_rate
    FROM wage_orders
    WHERE authority = v_authority
      AND p_check_date BETWEEN valid_from AND valid_to;

    IF v_base_rate IS NULL THEN
        RETURN NULL;
    END IF;

    -- Return Base Rate + Fixed Allowance (if any)
    RETURN v_base_rate + COALESCE(v_fixed_allowance, 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_financial_year(input_date date)
 RETURNS character varying
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    year_part INT;
    month_part INT;
    fy_start INT;
    fy_end INT;
BEGIN
    year_part := EXTRACT(YEAR FROM input_date);
    month_part := EXTRACT(MONTH FROM input_date);

    -- If month is Jan(1), Feb(2), or Mar(3), it belongs to the previous calendar year's FY start
    IF month_part < 4 THEN
        fy_start := year_part - 1;
        fy_end := year_part;
    ELSE
        fy_start := year_part;
        fy_end := year_part + 1;
    END IF;

    -- Format as YYYY-YY (taking last 2 digits of end year)
    RETURN fy_start || '-' || to_char(fy_end % 100, 'fm00');
END;
$function$

CREATE OR REPLACE FUNCTION public.log_activity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_user_id INT;
    v_old_data JSONB;
    v_new_data JSONB;
    v_record_id INT;
BEGIN
    -- Get User ID
    BEGIN v_user_id := current_setting('app.current_user_id', true)::INT; EXCEPTION WHEN OTHERS THEN v_user_id := NULL; END;

    -- Determine Record ID based on Table Name
    IF TG_TABLE_NAME = 'office' THEN
        IF TG_OP = 'DELETE' THEN v_record_id := OLD.Officeid; ELSE v_record_id := NEW.Officeid; END IF;
    ELSE
        -- Default to 'id' for all other tables
        IF TG_OP = 'DELETE' THEN v_record_id := OLD.id; ELSE v_record_id := NEW.id; END IF;
    END IF;

    IF (TG_OP = 'DELETE') THEN
        v_old_data := to_jsonb(OLD);
        INSERT INTO activity_logs (table_name, record_id, action, old_data, changed_by) VALUES (TG_TABLE_NAME, v_record_id, 'DELETE', v_old_data, v_user_id);
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        v_old_data := to_jsonb(OLD);
        v_new_data := to_jsonb(NEW);
        IF v_old_data IS DISTINCT FROM v_new_data THEN
            INSERT INTO activity_logs (table_name, record_id, action, old_data, new_data, changed_by) VALUES (TG_TABLE_NAME, v_record_id, 'UPDATE', v_old_data, v_new_data, v_user_id);
        END IF;
        RETURN NEW;
    ELSIF (TG_OP = 'INSERT') THEN
        v_new_data := to_jsonb(NEW);
        INSERT INTO activity_logs (table_name, record_id, action, new_data, changed_by) VALUES (TG_TABLE_NAME, v_record_id, 'INSERT', v_new_data, v_user_id);
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$function$

