CREATE OR REPLACE FUNCTION public.process_agency_data()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    formatted_name TEXT;
    clean_name TEXT;
BEGIN
    -- 1. Format Name: Ensure "M/s " prefix and Title Case
    formatted_name := NEW.name;

    -- Remove existing prefix variations (case insensitive) to avoid double prefixing like "M/s M/s Name"
    -- Regex removes 'M/s', 'm/s', 'M/S' followed by optional spaces at the start
    clean_name := regexp_replace(formatted_name, '^(m/s|M/S|M/s)\.?\s*', '', 'i');

    -- Apply Title Case to the name part (e.g., "ashok kumar" -> "Ashok Kumar")
    clean_name := initcap(clean_name);

    -- Prepend the standard "M/s "
    NEW.name := 'M/s ' || clean_name;

    -- 2. Validate PAN (if provided)
    IF NEW.pan_no IS NOT NULL AND length(trim(NEW.pan_no)) > 0 THEN
        NEW.pan_no := upper(trim(NEW.pan_no));
        -- Regex: 5 letters, 4 digits, 1 letter
        IF NEW.pan_no !~ '^[A-Z]{5}[0-9]{4}[A-Z]{1}$' THEN
            RAISE EXCEPTION 'Invalid PAN format. Must be 5 letters, 4 digits, 1 letter (e.g., ABCDE1234F).';
        END IF;
    ELSE
        NEW.pan_no := NULL; -- Ensure empty string becomes NULL
    END IF;

    -- 3. Validate GST (if provided)
    IF NEW.gst_no IS NOT NULL AND length(trim(NEW.gst_no)) > 0 THEN
        NEW.gst_no := upper(trim(NEW.gst_no));
        -- Regex: 2 digits, 5 letters, 4 digits, 1 letter, 1 alphanumeric, 'Z', 1 alphanumeric
        IF NEW.gst_no !~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$' THEN
            RAISE EXCEPTION 'Invalid GST format. Standard format is required (e.g., 07ABCDE1234F1Z5).';
        END IF;

        -- Check if GST contains the PAN (characters 3 to 12 of GST must match PAN)
        -- If PAN is also provided, we strictly check against it.
        -- If PAN is NOT provided, we could optionally extract it from GST, but let's stick to validation.
        IF NEW.pan_no IS NOT NULL THEN
            IF substring(NEW.gst_no from 3 for 10) <> NEW.pan_no THEN
                RAISE EXCEPTION 'GST Number (%) does not match the provided PAN (%).', NEW.gst_no, NEW.pan_no;
            END IF;
        END IF;
    ELSE
        NEW.gst_no := NULL;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_employee_data()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    base_name TEXT;
    name_count INT;
    suffix TEXT;
    roman_map TEXT[] := ARRAY['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];
BEGIN
    -- 1. Format Name to Title Case
    base_name := initcap(trim(NEW.full_name));
    NEW.full_name := base_name;

    -- 2. Handle Name Conflicts
    SELECT count(*) INTO name_count
    FROM employees
    WHERE full_name ~ ('^' || base_name || '(-\w+)?$')
      AND agreement_id = NEW.agreement_id;

    IF name_count > 0 THEN
        -- Append the next Roman numeral
        suffix := '-' || roman_map[name_count + 1];
        NEW.full_name := base_name || suffix;
    END IF;

    -- 3. Handle Reliever Logic
    IF NEW.is_reliever = TRUE THEN
        NEW.default_rest_day := NULL;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_office_name()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    words TEXT[];
    word TEXT;
    code TEXT := '';
    formatted_name TEXT;
BEGIN
    -- Part 1: Format the OfficeName
    -- Apply title case to the whole name first
    formatted_name := initcap(NEW.OfficeName);

    -- Handle specific acronyms as per the example "DDA".
    -- This is a simplistic approach. A more robust solution might use a dictionary table of acronyms.
    formatted_name := REPLACE(formatted_name, ' Dda', ' DDA');
    NEW.OfficeName := formatted_name;

    -- Part 2: Generate the OfficeCode from the newly formatted name
    -- Split the office name into words
    words := regexp_split_to_array(formatted_name, E'\\s+|,\\s*');

    -- Iterate through words and take the first letter
    FOREACH word IN ARRAY words
    LOOP
        -- Skip empty strings that might result from multiple spaces
        IF length(word) > 0 THEN
            code := code || upper(substring(word from 1 for 1));
        END IF;
    END LOOP;

    -- Assign the generated code
    NEW.OfficeCode = code;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.restrict_agreement_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_role TEXT;
BEGIN
    BEGIN
        v_role := current_setting('app.current_user_role', true);
    EXCEPTION WHEN OTHERS THEN
        v_role := 'guest';
    END;

    -- Superuser can edit anything
    IF v_role = 'superuser' THEN
        RETURN NEW;
    END IF;

    -- Manager can only edit specific columns
    -- Columns allowed: effective_boq (Scope), tendered_amount (AES Amount), period (To Date/Duration)
    IF v_role = 'manager' THEN
        IF (NEW.officeid IS DISTINCT FROM OLD.officeid) OR
           (NEW.aa_es_id IS DISTINCT FROM OLD.aa_es_id) OR
           (NEW.agency_id IS DISTINCT FROM OLD.agency_id) OR
           (NEW.agreement_no IS DISTINCT FROM OLD.agreement_no) OR
           (NEW.start_date IS DISTINCT FROM OLD.start_date) OR
           (NEW.status IS DISTINCT FROM OLD.status) THEN
            RAISE EXCEPTION 'Managers can only edit Scope, Amount, and Period of an Agreement.';
        END IF;
        RETURN NEW;
    END IF;

    -- Staff cannot edit at all (handled by RLS/PermissionManager, but double check here)
    IF v_role = 'staff' THEN
        RAISE EXCEPTION 'Staff are not allowed to edit Agreements.';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tm_dependents_validator(dependents_data jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    dep RECORD;
    age_years INTEGER;
BEGIN
    -- Check if it's an array
    IF jsonb_typeof(dependents_data) != 'array' THEN
        RETURN FALSE;
    END IF;

    FOR dep IN SELECT * FROM jsonb_to_recordset(dependents_data) AS x(name TEXT, relation TEXT, dob DATE)
    LOOP
        -- 1. Relation Check
        IF dep.relation NOT IN ('Spouse', 'Son', 'Daughter') THEN
            RAISE NOTICE 'Invalid relation: %', dep.relation;
            RETURN FALSE;
        END IF;

        -- 2. Age Check for Children
        IF dep.relation IN ('Son', 'Daughter') THEN
            age_years := extract(year from age(CURRENT_DATE, dep.dob));
            IF age_years < 5 OR age_years > 21 THEN
                RAISE NOTICE 'Child % outside age range (5-21): %', dep.name, age_years;
                RETURN FALSE;
            END IF;
        END IF;

        -- Basic name check
        IF dep.name IS NULL OR length(dep.name) < 2 THEN
            RETURN FALSE;
        END IF;
    END LOOP;

    RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.tm_payment_calculator(p_office_id integer, p_dependents jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_main_rate NUMERIC;
    v_dep_rate NUMERIC;
    v_icard_rate NUMERIC;
    v_gst_percent NUMERIC;
    v_dep_count INTEGER;
    v_subtotal NUMERIC;
    v_total NUMERIC;
BEGIN
    -- 1. Fetch active rates and settings
    SELECT main_member_rate, dependent_rate, icard_rate, gst_percent 
    INTO v_main_rate, v_dep_rate, v_icard_rate, v_gst_percent
    FROM public.tm_rates
    WHERE office_id = p_office_id AND is_active = TRUE
    ORDER BY effective_from DESC
    LIMIT 1;

    -- Fallback rates
    IF NOT FOUND THEN
        v_main_rate := 5000; v_dep_rate := 1500; v_icard_rate := 10; v_gst_percent := 18;
    END IF;

    -- 2. Count dependents
    v_dep_count := jsonb_array_length(p_dependents);

    -- 3. Calculate Subtotal (Base Rates + I-Cards for all)
    -- Total members = 1 (main) + v_dep_count
    v_subtotal := v_main_rate + (v_dep_count * v_dep_rate) + ((1 + v_dep_count) * v_icard_rate);

    -- 4. Add GST
    v_total := v_subtotal * (1 + (v_gst_percent / 100));

    RETURN round(v_total, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.tm_tmno_generator(p_office_id integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_serial INTEGER;
    v_office_code TEXT;
    v_month TEXT;
    v_year TEXT;
BEGIN
    v_month := to_char(CURRENT_DATE, 'MM');
    v_year := to_char(CURRENT_DATE, 'YYYY');

    -- Get Office Code
    SELECT officecode INTO v_office_code FROM public.office WHERE officeid = p_office_id;
    v_office_code := COALESCE(v_office_code, 'GEN');

    -- Get Serial (Resetting annually)
    SELECT COALESCE(MAX(SUBSTRING(tm_no FROM '^(\d+)')::INTEGER), 0) + 1 
    INTO v_serial 
    FROM public.tm 
    WHERE tm_no LIKE '%/' || v_year;

    RETURN LPAD(v_serial::TEXT, 2, '0') || '/' || v_office_code || '/' || v_month || '/' || v_year;
END;
$function$

CREATE OR REPLACE FUNCTION public.tm_tmno_generator()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    next_val INTEGER;
    current_year TEXT;
BEGIN
    current_year := to_char(CURRENT_DATE, 'YYYY');
    -- Get next sequence value (or simple count for stub)
    SELECT COALESCE(MAX(id), 0) + 1 INTO next_val FROM public.tm;
    RETURN 'TM/' || current_year || '/' || LPAD(next_val::TEXT, 5, '0');
END;
$function$

CREATE OR REPLACE FUNCTION public.tm_validator()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- 1. Auto-generate TM No if not provided
    IF NEW.tm_no IS NULL OR NEW.tm_no = '' THEN
        NEW.tm_no := public.tm_tmno_generator(NEW.office_id);
    END IF;

    -- 2. Calculate Validity
    NEW.validity := public.tm_validity(CURRENT_DATE);

    -- 3. Calculate Payment Amount (Base + Deps + ICards + GST)
    NEW.payment_amount := public.tm_payment_calculator(NEW.office_id, NEW.dependents);

    -- 4. Strict Dependents Validation
    IF NOT public.tm_dependents_validator(NEW.dependents) THEN
        RAISE EXCEPTION 'Dependent validation failed. Check relations and ages (Children must be 5-21).';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tm_validity(p_application_date date)
 RETURNS daterange
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_start_date DATE;
    v_end_date DATE;
BEGIN
    -- If application is on or after 26th, start from 1st of next month
    IF extract(day from p_application_date) >= 26 THEN
        v_start_date := (date_trunc('month', p_application_date) + INTERVAL '1 month')::DATE;
    ELSE
        -- Otherwise start from 1st of current month
        v_start_date := date_trunc('month', p_application_date)::DATE;
    END IF;

    -- Validity is for 3 calendar months
    v_end_date := (v_start_date + INTERVAL '3 months')::DATE;

    RETURN daterange(v_start_date, v_end_date);
END;
$function$

