CREATE OR REPLACE FUNCTION public.validate_and_calculate_bill()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    link_count INT;
    v_budget_id INT;
BEGIN
    -- 1. Validation Logic
    IF NEW.bill_type = 'Compliance' THEN
        IF NEW.budget_id IS NULL THEN
            RAISE EXCEPTION 'Compliance bills must have a Budget ID selected by the user.';
        END IF;
        NEW.agreement_id := NULL;
        NEW.work_order_id := NULL;
        NEW.supply_order_id := NULL;
    ELSE
        link_count := (CASE WHEN NEW.agreement_id IS NOT NULL THEN 1 ELSE 0 END) +
                      (CASE WHEN NEW.work_order_id IS NOT NULL THEN 1 ELSE 0 END) +
                      (CASE WHEN NEW.supply_order_id IS NOT NULL THEN 1 ELSE 0 END);
        IF link_count != 1 THEN
            RAISE EXCEPTION 'A non-compliance bill must be linked to exactly one item (Agreement, Work Order, or Supply Order).';
        END IF;

        -- Automatically find the budget_id from the linked item's AA&ES
        IF NEW.agreement_id IS NOT NULL THEN
            -- CORRECTED: Use 'budgetid' instead of 'budget_id'
            SELECT ae.budgetid INTO v_budget_id FROM agreements ag JOIN aa_es ae ON ag.aa_es_id = ae.id WHERE ag.id = NEW.agreement_id;
        END IF;

        IF v_budget_id IS NULL THEN
            RAISE EXCEPTION 'Could not find a linked budget for the selected Agreement/Work Order/Supply Order. Please check the AA&ES.';
        END IF;

        NEW.budget_id := v_budget_id;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_attendance_dates()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_joining DATE;
    v_leaving DATE;
BEGIN
    SELECT joining_date, leaving_date INTO v_joining, v_leaving
    FROM employees WHERE id = NEW.employee_id;

    IF NEW.attendance_date < v_joining THEN
        RAISE EXCEPTION 'Attendance Error: Cannot mark attendance for % on % (Joined on %).', 
            (SELECT full_name FROM employees WHERE id = NEW.employee_id), NEW.attendance_date, v_joining;
    END IF;

    IF v_leaving IS NOT NULL AND NEW.attendance_date > v_leaving THEN
        RAISE EXCEPTION 'Attendance Error: Cannot mark attendance for % on % (Left on %).', 
            (SELECT full_name FROM employees WHERE id = NEW.employee_id), NEW.attendance_date, v_leaving;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_budget_availability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        DECLARE
            budget_provision DECIMAL(15, 2);
            used_amount DECIMAL(15, 2);
        BEGIN
            SELECT provision * 100000 INTO budget_provision FROM budget WHERE id = NEW.budgetid;
            IF NOT FOUND THEN RAISE EXCEPTION 'Invalid Budget ID selected.'; END IF;

            SELECT COALESCE(SUM(aa_es_amount), 0) INTO used_amount FROM aa_es WHERE budgetid = NEW.budgetid AND id IS DISTINCT FROM NEW.id;

            IF (used_amount + NEW.aa_es_amount) > budget_provision THEN
                RAISE EXCEPTION 'Insufficient Budget. Provision: %, Used: %, Requested: %. Total exceeds limit.', budget_provision, used_amount, NEW.aa_es_amount;
            END IF;
            RETURN NEW;
        END;
        $function$

CREATE OR REPLACE FUNCTION public.validate_dependent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_member_type membership_type;
    v_age INTERVAL;
    v_years INT;
BEGIN
    -- 1. Check Member Type
    SELECT membership_type INTO v_member_type FROM members WHERE id = NEW.member_id;

    IF v_member_type = 'Associate' THEN
        RAISE EXCEPTION 'Associate Members cannot have dependents.';
    END IF;

    -- 2. Check Spouse Limit
    IF NEW.relationship = 'Spouse' THEN
        IF EXISTS (SELECT 1 FROM dependents WHERE member_id = NEW.member_id AND relationship = 'Spouse' AND id IS DISTINCT FROM NEW.id AND status = 'Active') THEN
            RAISE EXCEPTION 'Member already has an active spouse registered.';
        END IF;
    END IF;

    -- 3. Check Age for Children
    IF NEW.relationship IN ('Son', 'Daughter') THEN
        v_age := age(CURRENT_DATE, NEW.dob);
        v_years := date_part('year', v_age);

        IF v_years < 5 THEN
            RAISE EXCEPTION 'Child must be at least 5 years old.';
        END IF;

        IF v_years >= 21 THEN
            RAISE EXCEPTION 'Child must be under 21 years old.';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_hand_receipt_budget()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_provision DECIMAL(15, 2);
    v_used DECIMAL(15, 2);
BEGIN
    -- Only check if budget implication is TRUE
    IF NEW.budget_implication THEN
        -- Get budget provision (converted from Lacs to absolute)
        SELECT provision * 100000 INTO v_provision FROM budget WHERE id = NEW.budgetid;

        -- Calculate used amount (Bills + other Hand Receipts)
        SELECT COALESCE(SUM(net_amount), 0) INTO v_used FROM bills WHERE budget_id = NEW.budgetid;
        v_used := v_used + (SELECT COALESCE(SUM(net_amount), 0) FROM hand_receipts WHERE budgetid = NEW.budgetid AND id <> NEW.id AND budget_implication = TRUE);

        IF (v_used + NEW.net_amount) > v_provision THEN
            RAISE EXCEPTION 'Insufficient Budget for this Hand Receipt. Available: %, Required: %', (v_provision - v_used), NEW.net_amount;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_wage_rates_json()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    r RECORD;
