    FOR r IN SELECT DISTINCT json_key FROM wage_items WHERE authority = NEW.authority
    LOOP
        IF NOT (NEW.rates ? r.json_key) THEN
            RAISE EXCEPTION 'Missing required rate for category: % in authority %', r.json_key, NEW.authority;
        END IF;

        IF (NEW.rates ->> r.json_key)::DECIMAL <= 0 THEN
             RAISE EXCEPTION 'Rate for % must be greater than zero.', r.json_key;
        END IF;
