    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_wages_ledger_entry()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Rule 1: Credit entries can only be on the last day of the month.
    IF NEW.cr_amount > 0 AND NEW.transaction_date != (date_trunc('month', NEW.transaction_date) + interval '1 month - 1 day')::date THEN
        RAISE EXCEPTION 'Credit entries can only be posted on the last day of the month. Attempted for %', NEW.transaction_date;
    END IF;
    RETURN NEW;
END;
$function$
